    for line in f:
        parts = line.strip().split(';')
        if len(parts) < 6:
            continue
        cp = int(parts[0], 16)
        name = parts[1]
        decomp = parts[5]
        if '<compat>' in decomp:
            decomp_cps = [int(x, 16) for x in decomp.replace('<compat>', '').strip().split()]
            if all(c < 0x80 for c in decomp_cps):
                if cp < 0x80:
                    utf8_len = 1
                elif cp < 0x800:
                    utf8_len = 2
                elif cp < 0x10000:
                    utf8_len = 3
                else:
                    utf8_len = 4
